import fs from 'node:fs';import {createHash} from 'node:crypto';import {gzipSync,gunzipSync} from 'node:zlib';
import {buildModel,MODEL_NAMES} from './models.js';import {analyzeDifficulty,validateCandidate} from './quality.js';import {javaExpression} from './ir.js';
const sourceDigest=createHash('sha256').update(fs.readdirSync(new URL('.',import.meta.url)).filter(f=>f.endsWith('.js')).sort().map(f=>f+'\n'+fs.readFileSync(new URL(f,import.meta.url),'utf8')).join('\n')).digest('hex');
const gallery=JSON.parse(fs.readFileSync(new URL('../reports/instructional-review-gallery.json',import.meta.url))),decisionsFile=new URL('../reports/review-decisions.json.gz',import.meta.url),decisions=fs.existsSync(decisionsFile)?JSON.parse(gunzipSync(fs.readFileSync(decisionsFile))):{};
const records=gallery.map((sample,i)=>{
  const q=buildModel(sample.mode,MODEL_NAMES[sample.mode].indexOf(sample.model),sample.variant,sample.difficulty,sample.seed);if(q.code!==sample.code||q.correctAnswer!==sample.answer)throw Error(`Review sample ${i+1} is stale`);
  const {features,run,minimumBand}=analyzeDifficulty(q.semanticProgram),check=validateCandidate(q),hash=createHash('sha256').update(JSON.stringify([q.format,q.difficulty,q.reasoningModel,q.structuralVariant,q.seed,q.code,q.answer,q.choices])).digest('hex');
  const observation=q.semanticProgram.output,goal=observation.op==='cell-index'?`Locate ${javaExpression(observation.index)}${observation.column?`, ${javaExpression(observation.column)}`:''}`:observation.op==='cell-pair'?`Locate ${javaExpression(observation.left)} and ${javaExpression(observation.right)}`:`Evaluate ${javaExpression(observation)}`;
  return {id:i+1,hash,...sample,sourceDigest,independentAnalysis:{features,minimumBand,semanticAnswer:String(run.answer),minimumSolutionPath:{goal,requiredChanges:run.slice.filter(e=>!['initial','allocation','loop-index','loop-test'].includes(e.kind)).map(e=>({statement:e.statement,kind:e.kind,location:e.key,value:e.value})),structuralStages:run.structuralDepth},automaticProblems:check.problems},review:decisions[hash]||{status:'pending',reviewer:null,justified:null,easierShortcut:null,instructionalProblems:null}};
});
fs.writeFileSync(new URL('../reports/review-candidates.json',import.meta.url),JSON.stringify({sourceDigest,records},null,2));
if(process.argv.includes('--complete')){if(records.length!==720||records.some(r=>r.review.status!=='assistant-reviewed'))throw Error('All 720 records require an explicit review decision');fs.writeFileSync(new URL('../reports/instructional-review-720.json.gz',import.meta.url),gzipSync(JSON.stringify({sourceDigest,reviewType:'Structured assistant source/dataflow review; not an independent human review',records}),{level:9}));}
if(process.argv.includes('--complete')){
 const esc=value=>String(value).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 const body=records.map(r=>`<details><summary>${r.id}. ${esc(r.mode)} · ${r.difficulty} · ${esc(r.model)}</summary><p>${esc(r.prompt)}</p><pre>${esc(r.code)}</pre><p><strong>Answer:</strong> ${esc(r.answer)}</p><ol>${r.choices.map(c=>`<li><code>${esc(c)}</code></li>`).join('')}</ol><p><strong>Concept:</strong> ${esc(r.review.primaryConcept)}</p><p>${esc(r.review.reasoningAssessment)}</p><p><strong>Minimum path:</strong> ${esc(r.review.minimumLegitimatePath)}</p><p><strong>Shortcut review:</strong> ${esc(r.review.easierShortcut)}</p><p><strong>Difficulty justified:</strong> ${r.review.justified?'Yes (assistant assessment)':'No'}. Unresolved problems: ${r.review.instructionalProblems.length}.</p><small>Variant ${r.variant}; seed ${r.seed}; hash ${r.hash}</small></details>`).join('\n');
 fs.writeFileSync(new URL('../reports/instructional-review.html',import.meta.url),`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Array Lab — 720-sample instructional review</title><style>body{font:17px/1.55 system-ui;max-width:1000px;margin:auto;padding:1rem;color:#152c35;background:#f6fafb}details{border:1px solid #9ab3ba;border-radius:.4rem;margin:.7rem 0;padding:1rem;background:white}summary{cursor:pointer;font-weight:700}pre,code{white-space:pre-wrap;overflow-wrap:anywhere}small{overflow-wrap:anywhere}</style><h1>Array Lab instructional review</h1><p>720 reproducible samples: twenty per practice mode and difficulty. This is an <strong>assistant source/dataflow review</strong>, not an independent human audit. Automated semantic and JVM checks supplement the assessment; they do not constitute human review. No independent human sign-off is claimed.</p><p>The initial documented twenty-sample review rejected eighteen difficulty assignments and two shortcut defects. The affected generators were redesigned. Later source/sample findings repaired Boolean-result shortcuts, dead array updates, non-interacting stages, replacement-array distractors and excessive arithmetic workload.</p><p>Current runtime digest: <code>${sourceDigest}</code>. Complete source, metadata, independent dependency traces and decisions are in <a href="instructional-review-720.json.gz">the compressed review record</a>. <a href="IMPLEMENTATION_STATUS.md">Implementation report</a>.</p>${body}</html>`);
}
const group=Number(process.argv.find(a=>a.startsWith('--group='))?.split('=')[1]||0),modes=Object.keys(MODEL_NAMES).slice(group*3,group*3+3);
console.log('Tuple: id:model/variant = operations, structural stages, arithmetic, mutations, references, required data objects, loops, conditions; then minimum band.');
for(const mode of modes)for(const difficulty of ['Beginner','Intermediate','Advanced']){console.log('\n'+mode+'/'+difficulty);for(const r of records.filter(r=>r.mode===mode&&r.difficulty===difficulty)){const f=r.independentAnalysis.features;console.log(`${r.id}:${r.model}/${r.variant}=${[f.operations,r.independentAnalysis.minimumSolutionPath.structuralStages,f.arithmetic,f.mutations,f.references,f.requiredDataObjects,f.loops,f.conditions].join(',')} ${r.independentAnalysis.minimumBand}${r.independentAnalysis.automaticProblems.length?' PROBLEMS:'+r.independentAnalysis.automaticProblems.join(','):''}`);}}
